/**
 * Rich Menu definition: 2500x1686, 3 columns x 2 rows, one postback action per tile.
 * The image (assets/rich-menu/rich-menu.jpg) is generated by scripts/build-rich-menu.ts from the
 * same TILES list, so labels and tap areas can never drift apart.
 */
import type { PostbackAction } from '../../../infrastructure/line/messages.ts';
import type { MascotExpression } from '../mascot.ts';
import { encodePostback, type ActionName } from '../postback.ts';

export const RICH_MENU_SIZE = { width: 2500, height: 1686 } as const;
export const RICH_MENU_NAME = 'ShikSheek main v1';

export interface RichMenuTile {
  action: ActionName;
  labelTh: string;
  labelEn: string;
  displayText: string;
  mascot: MascotExpression;
  theme: 'red' | 'yellow' | 'white' | 'deepRed';
  openKeyboard?: boolean;
}

/** Order = left→right, top→bottom. */
export const TILES: readonly RichMenuTile[] = [
  { action: 'dashboard', labelTh: 'ภาพรวม', labelEn: 'DASHBOARD', displayText: 'ภาพรวม', mascot: 'encouraging', theme: 'red' },
  { action: 'add_expense', labelTh: 'จดรายจ่าย', labelEn: 'ADD EXPENSE', displayText: 'จดรายจ่าย', mascot: 'worried', theme: 'yellow', openKeyboard: true },
  { action: 'add_income', labelTh: 'จดรายรับ', labelEn: 'ADD INCOME', displayText: 'จดรายรับ', mascot: 'saving', theme: 'white', openKeyboard: true },
  { action: 'fixed_costs', labelTh: 'ค่าใช้จ่ายประจำ', labelEn: 'FIXED COSTS', displayText: 'ค่าใช้จ่ายประจำ', mascot: 'discipline', theme: 'white' },
  { action: 'budgets', labelTh: 'งบประมาณ', labelEn: 'BUDGETS', displayText: 'งบประมาณ', mascot: 'smart', theme: 'white' },
  { action: 'reports', labelTh: 'รายงาน', labelEn: 'REPORTS', displayText: 'รายงาน', mascot: 'planning', theme: 'deepRed' },
];

export function tileBounds(index: number) {
  const col = index % 3;
  const r = Math.floor(index / 3);
  const xs = [0, 833, 1666, 2500];
  const ys = [0, 843, 1686];
  return { x: xs[col]!, y: ys[r]!, width: xs[col + 1]! - xs[col]!, height: ys[r + 1]! - ys[r]! };
}

export function richMenuDefinition() {
  return {
    size: RICH_MENU_SIZE,
    selected: true,
    name: RICH_MENU_NAME,
    chatBarText: 'เมนูชิกชิก 🐔',
    areas: TILES.map((t, i) => {
      const action: PostbackAction = { type: 'postback', label: t.labelTh, data: encodePostback(t.action), displayText: t.displayText };
      if (t.openKeyboard) action.inputOption = 'openKeyboard';
      return { bounds: tileBounds(i), action };
    }),
  };
}
